package com.openminis.app.ui.chat

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.math.abs

/**
 * [T-native-composer-slider] Pure-JVM checks for the ported effort slider.
 *
 * The expected numbers are **golden values from the upstream bundle**
 * (`Bai-2008/dsh-better-panel` @ `4f798ffc`, `lib/client.js`), generated by
 * running the original `pctFromIndex` / `mappingOf` / `fillColorFor` /
 * `energyFor` / `speedFor` / `PARTICLES` / `star*` functions in Node. They pin
 * the drawing and animation maths the Canvas relies on:
 *
 *  - a 1/3 pitch detent (`floor(u - 1/3) + 1`), nearest-stop press;
 *  - the blue -> violet -> deep ramp and the 1/3 .. 2/3 energy window;
 *  - 0 stars at Off/Low, 11 at high (2/3), 22 at Max — the upstream gate that
 *    the old always-on bed intentionally overrode;
 *  - the deterministic 22-star table (golden-ratio phase, slot-searched Y),
 *    brightness, duration and negative phase delay.
 */
class ComposerPortMathTest {

    @Test
    fun `level positions are discrete and clamped`() {
        assertEquals(0f, ComposerPortMath.pct(0, 7), 0f)
        assertEquals(1f, ComposerPortMath.pct(6, 7), 0f)
        // Upstream `pctFromIndex` returns 0 for a single level, not 1.
        assertEquals(0f, ComposerPortMath.pct(0, 1), 0f)
        assertEquals(1f, ComposerPortMath.pct(99, 7), 0f)
        assertEquals(0f, ComposerPortMath.pct(-3, 7), 0f)
        assertEquals(0.5f, ComposerPortMath.pct(1, 3), 0f)
    }

    @Test
    fun `nearest index snaps to the closest stop`() {
        assertEquals(0, ComposerPortMath.nearestIndex(0f, 7))
        assertEquals(3, ComposerPortMath.nearestIndex(0.5f, 7))
        assertEquals(6, ComposerPortMath.nearestIndex(1f, 7))
        assertEquals(0, ComposerPortMath.nearestIndex(-2f, 7))
        assertEquals(6, ComposerPortMath.nearestIndex(2f, 7))
        assertEquals(0, ComposerPortMath.nearestIndex(0.7f, 1))
    }

    @Test
    fun `detent fires one third of a pitch past the current stop`() {
        // u is in level units: 0 .. count-1. Four stops: off/low/high/max.
        assertEquals(0, ComposerPortMath.detentIndex(0f, 4))
        assertEquals(0, ComposerPortMath.detentIndex(0.32f, 4))
        assertEquals(1, ComposerPortMath.detentIndex(1f / 3f, 4))
        assertEquals(1, ComposerPortMath.detentIndex(0.5f, 4))
        assertEquals(1, ComposerPortMath.detentIndex(1.32f, 4))
        assertEquals(2, ComposerPortMath.detentIndex(1.34f, 4))
        assertEquals(2, ComposerPortMath.detentIndex(2.32f, 4))
        assertEquals(3, ComposerPortMath.detentIndex(2.34f, 4))
        // Clamped at both ends.
        assertEquals(0, ComposerPortMath.detentIndex(-5f, 4))
        assertEquals(3, ComposerPortMath.detentIndex(9f, 4))
        assertEquals(0, ComposerPortMath.detentIndex(0.9f, 1))
        // Seven stops: threshold is still +1/3 pitch, not +1/2.
        assertEquals(2, ComposerPortMath.detentIndex(2.32f, 7))
        assertEquals(3, ComposerPortMath.detentIndex(2.34f, 7))
    }

    @Test
    fun `press dead zone only holds on a nearest-detent conflict`() {
        // Press at u=0.2 -> nearest 0, detent 0: no conflict, the detent talks.
        assertFalse(
            ComposerPortMath.deadzoneHolds(
                unit = 0.4f, pressUnit = 0.2f, mapped = 1, pressIndex = 0,
                conflict = false, active = true,
            ),
        )
        // Conflict (nearest 0, detent says 1 at press): hold until +1/3 pitch.
        assertTrue(
            ComposerPortMath.deadzoneHolds(
                unit = 0.3f, pressUnit = 0.05f, mapped = 1, pressIndex = 0,
                conflict = true, active = true,
            ),
        )
        assertFalse(
            ComposerPortMath.deadzoneHolds(
                unit = 0.40f, pressUnit = 0.05f, mapped = 1, pressIndex = 0,
                conflict = true, active = true,
            ),
        )
        // Once the detent agrees with the pressed stop, the press is released.
        assertFalse(
            ComposerPortMath.deadzoneHolds(
                unit = 0.1f, pressUnit = 0.05f, mapped = 0, pressIndex = 0,
                conflict = true, active = true,
            ),
        )
        assertFalse(
            ComposerPortMath.deadzoneHolds(
                unit = 0.1f, pressUnit = 0.05f, mapped = 1, pressIndex = 0,
                conflict = true, active = false,
            ),
        )
    }

    @Test
    fun `energy starts at the first third and reaches one at max`() {
        assertEquals(0f, ComposerPortMath.energy(0f), 0f)
        assertEquals(0f, ComposerPortMath.energy(1f / 3f), 0f)
        assertEquals(0.25f, ComposerPortMath.energy(0.5f), 1e-5f)
        assertEquals(0.5f, ComposerPortMath.energy(2f / 3f), 1e-5f)
        assertEquals(1f, ComposerPortMath.energy(1f), 1e-5f)
        assertEquals(0f, ComposerPortMath.energy(-1f), 0f)
        assertEquals(1f, ComposerPortMath.energy(2f), 1e-5f)
    }

    @Test
    fun `fill endpoint follows blue violet deep`() {
        assertEquals(ComposerPortMath.BLUE_ARGB, ComposerPortMath.fillEndArgb(0f))
        assertEquals(ComposerPortMath.BLUE_ARGB, ComposerPortMath.fillEndArgb(1f / 6f))
        assertEquals(ComposerPortMath.BLUE_ARGB, ComposerPortMath.fillEndArgb(1f / 3f))
        assertColorEquals(0xFF7063F1.toInt(), ComposerPortMath.fillEndArgb(0.5f))
        assertColorEquals(0xFF9333EA.toInt(), ComposerPortMath.fillEndArgb(2f / 3f))
        assertColorEquals(0xFF7028C0.toInt(), ComposerPortMath.fillEndArgb(5f / 6f))
        assertEquals(ComposerPortMath.DEEP_ARGB, ComposerPortMath.fillEndArgb(1f))
        assertEquals(ComposerPortMath.BLUE_ARGB, ComposerPortMath.FILL_START_ARGB)
    }

    @Test
    fun `off chip stays neutral and higher levels brighten`() {
        assertEquals(ComposerPortMath.OFF_GREY_ARGB, ComposerPortMath.levelColorArgb(0, 4))
        assertNotEquals(ComposerPortMath.OFF_GREY_ARGB, ComposerPortMath.levelColorArgb(3, 4))
        assertEquals(
            ComposerPortMath.mixArgb(ComposerPortMath.BLUE_ARGB, ComposerPortMath.TEXT_VIOLET_ARGB, 0.5f),
            ComposerPortMath.levelColorArgb(2, 4),
        )
    }

    @Test
    fun `colour mixing stays opaque and bounded`() {
        assertEquals(
            0xFF000000.toInt(),
            ComposerPortMath.mixArgb(0xFF000000.toInt(), 0xFFFFFFFF.toInt(), 0f),
        )
        assertEquals(
            0xFFFFFFFF.toInt(),
            ComposerPortMath.mixArgb(0xFF000000.toInt(), 0xFFFFFFFF.toInt(), 1f),
        )
        val half = ComposerPortMath.mixArgb(0xFF000000.toInt(), 0xFFFFFFFF.toInt(), 0.5f)
        assertTrue(((half shr 16) and 0xFF) in 127..128)
    }

    @Test
    fun `stars are gated by energy exactly like upstream`() {
        assertEquals(0, ComposerPortMath.starCountFor(0f))
        assertEquals(0, ComposerPortMath.starCountFor(1f / 6f))
        assertEquals(0, ComposerPortMath.starCountFor(1f / 3f))
        assertEquals(6, ComposerPortMath.starCountFor(0.5f))
        assertEquals(11, ComposerPortMath.starCountFor(2f / 3f))
        assertEquals(ComposerPortMath.PARTICLE_COUNT, ComposerPortMath.starCountFor(1f))
        assertEquals(ComposerPortMath.PARTICLE_COUNT, ComposerPortMath.starCountFor(2f))
    }

    @Test
    fun `star layer opacity follows energy`() {
        assertEquals(0.6f, ComposerPortMath.starLayerOpacityFor(0f), 1e-5f)
        assertEquals(0.6f, ComposerPortMath.starLayerOpacityFor(1f / 3f), 1e-5f)
        assertEquals(0.8f, ComposerPortMath.starLayerOpacityFor(2f / 3f), 1e-5f)
        assertEquals(1f, ComposerPortMath.starLayerOpacityFor(1f), 1e-5f)
    }

    @Test
    fun `particle speed keeps the upstream 0_35x to 2x envelope`() {
        assertEquals(0.35f, ComposerPortMath.speedFor(0f), 0f)
        assertEquals(0.35f, ComposerPortMath.speedFor(1f / 6f), 0f)
        assertEquals(0.35f, ComposerPortMath.speedFor(1f / 3f), 0f)
        assertEquals(0.5f, ComposerPortMath.speedFor(0.5f), 1e-5f)
        assertEquals(1f, ComposerPortMath.speedFor(2f / 3f), 1e-5f)
        assertEquals(2f, ComposerPortMath.speedFor(1f), 1e-5f)
    }

    @Test
    fun `particle table matches the upstream build`() {
        // Golden Y slot percentages, in index order (upstream PARTICLES).
        val goldenY = intArrayOf(
            52, 84, 64, 16, 92, 44, 76, 56, 88, 40, 36,
            68, 48, 80, 32, 28, 60, 12, 72, 24, 20, 8,
        )
        val particles = ComposerPortMath.PARTICLES
        assertEquals(ComposerPortMath.PARTICLE_COUNT, particles.size)
        for (i in goldenY.indices) {
            assertEquals("particle $i y", goldenY[i].toFloat(), particles[i].yPercent, 1e-3f)
            assertTrue(particles[i].phase in 0f..1f)
        }
        // Phases are the golden-ratio sequence, all distinct.
        for (i in 0 until 4) {
            val expected = ((i + 1) * ComposerPortMath.GOLDEN_RATIO) % 1.0
            assertEquals("phase $i", expected, particles[i].phase.toDouble(), 1e-6)
        }
        assertEquals(
            particles.size,
            particles.map { it.phase }.toSet().size,
        )
        // Phase neighbours are at least MIN_HEIGHT_SLOTS (3 slots = 12% apart).
        val byPhase = particles.sortedBy { it.phase }
        for (i in 1 until byPhase.size) {
            assertTrue(
                "phase neighbours ${i - 1}/$i are too close vertically",
                abs(byPhase[i].yPercent - byPhase[i - 1].yPercent) >= 12f - 1e-3f,
            )
        }
    }

    @Test
    fun `star brightness duration and delay match the upstream values`() {
        assertEquals(0.6395f, ComposerPortMath.starBrightnessFor(0), 1e-6f)
        assertEquals(0.671f, ComposerPortMath.starBrightnessFor(1), 1e-6f)
        assertEquals(0.5765f, ComposerPortMath.starBrightnessFor(7), 1e-6f)
        assertEquals(0.9505f, ComposerPortMath.starBrightnessFor(21), 1e-6f)

        // speed = 1 (the high stop) -> 1.5s * 2/1 * spread.
        assertEquals(2.82192f, ComposerPortMath.starDurationFor(0, 1f), 1e-4f)
        assertEquals(2.78016f, ComposerPortMath.starDurationFor(1, 1f), 1e-4f)
        assertEquals(3.0096f, ComposerPortMath.starDurationFor(7, 1f), 1e-4f)
        assertEquals(3.00912f, ComposerPortMath.starDurationFor(21, 1f), 1e-4f)
        // Max: 1.5s * 2/2 * spread = 1.41096s for star 0; far left ~8.06s.
        assertEquals(1.41096f, ComposerPortMath.starDurationFor(0, 2f), 1e-4f)
        assertTrue(ComposerPortMath.starDurationFor(0, 0.35f) > 8f)

        assertEquals(-1.8757919f, ComposerPortMath.starDelayFor(0, 3f), 1e-4f)
        assertEquals(-0.7322339f, ComposerPortMath.starDelayFor(1, 3f), 1e-4f)
        assertEquals(-2.8901458f, ComposerPortMath.starDelayFor(7, 3f), 1e-4f)
        assertEquals(-1.8676432f, ComposerPortMath.starDelayFor(21, 3f), 1e-4f)
        // Delay is a negative phase of the same period.
        for (i in 0 until ComposerPortMath.PARTICLE_COUNT) {
            val d = ComposerPortMath.starDelayFor(i, 2f)
            assertTrue("delay $i", d <= 0f && d >= -2f)
            assertEquals(
                ComposerPortMath.starPhase(i),
                (-d / 2f),
                1e-5f,
            )
        }
    }

    @Test
    fun `star alpha transcribes the sweep keyframes`() {
        assertEquals(0f, ComposerPortMath.starAlpha(0f, 1f, 1f), 0f)
        assertEquals(1f, ComposerPortMath.starAlpha(0.06f, 1f, 1f), 1e-6f)
        assertEquals(1f, ComposerPortMath.starAlpha(0.5f, 1f, 1f), 0f)
        assertEquals(1f, ComposerPortMath.starAlpha(0.94f, 1f, 1f), 1e-6f)
        assertEquals(0f, ComposerPortMath.starAlpha(1f, 1f, 1f), 0f)
        assertEquals(0.5f, ComposerPortMath.starAlpha(0.03f, 1f, 1f), 1e-5f)
        // brightness and layer both scale the fade
        assertEquals(0.25f, ComposerPortMath.starAlpha(0.5f, 0.5f, 0.5f), 1e-6f)
        // clamped outside 0..1
        assertEquals(0f, ComposerPortMath.starAlpha(-1f, 1f, 1f), 0f)
        assertEquals(0f, ComposerPortMath.starAlpha(2f, 1f, 1f), 0f)
    }

    private fun assertColorEquals(expected: Int, actual: Int) {
        for (shift in intArrayOf(16, 8, 0)) {
            val e = (expected shr shift) and 0xFF
            val a = (actual shr shift) and 0xFF
            assertTrue(
                "channel $shift expected $e but was $a (expected #%08X, actual #%08X)"
                    .format(expected, actual),
                abs(e - a) <= 1,
            )
        }
        assertEquals(0xFF, (actual ushr 24) and 0xFF)
    }
}
